+     */
+    if (length == 0) {
+        /* XXX - return error indication */
+        strbuf = wmem_strbuf_new(wmem_packet_scope(), "");
+        return (guint8 *)wmem_strbuf_finalize(strbuf);
+    }
+    string_len = *ptr;
+    ptr++;
+    length--;
+
+    strbuf = wmem_strbuf_sized_new(wmem_packet_scope(), 2*string_len+1, 0);
+
+    /*
